function buildDefaultCompose(app) {
  if (app.id === "minecraft") {
    const mc = (state && state.minecraftStudio) ? state.minecraftStudio : {
      server_type: "PAPER", version: "1.21.4", memory_heap: "4G", use_aikar_flags: true,
      gamemode: "survival", difficulty: "normal", online_mode: true, max_players: 20,
      view_distance: 10, modrinth_projects: "viaversion,chunky", ops_list: "", whitelist: "",
      rcon_password: "instant-rcon-admin"
    };
    const crossplayPort = mc.server_type === "GEYSER_FLOODGATE" ? '\n      - "19132:19132/udp"' : "";
    const effType = mc.server_type === "GEYSER_FLOODGATE" ? "PAPER" : mc.server_type;
    return `name: minecraft
services:
  minecraft:
image: itzg/minecraft-server:latest
container_name: minecraft
restart: unless-stopped
tty: true
stdin_open: true
security_opt:
  - no-new-privileges:true
environment:
  - EULA=TRUE
  - TYPE=${effType}
  - VERSION=${mc.version}
  - MEMORY=${mc.memory_heap}
  - USE_AIKAR_FLAGS=${mc.use_aikar_flags}
  - MODE=${mc.gamemode}
  - DIFFICULTY=${mc.difficulty}
  - ONLINE_MODE=${mc.online_mode}
  - MAX_PLAYERS=${mc.max_players}
  - VIEW_DISTANCE=${mc.view_distance}
  - MODRINTH_PROJECTS=${mc.modrinth_projects}
  - OPS=${mc.ops_list}
  - ENABLE_RCON=true
  - RCON_PASSWORD=${mc.rcon_password}
ports:
  - "25565:25565/tcp"
  - "127.0.0.1:25575:25575/tcp"${crossplayPort}
volumes:
  - /DATA/AppData/minecraft/data:/data`;
  }
  const spec = VERIFIED_INTERNAL_PORTS[app.id] || {};
  const intPort = spec.intPort || app.port;
  const portLines = [];
  if (!spec.udpOnly) {
    portLines.push(`      - "${app.port}:${intPort}"`);
  } else {
    portLines.push(`      - "${app.port}:${intPort}/udp"`);
  }
  if (Array.isArray(spec.extraPorts)) {
    spec.extraPorts.forEach(ep => portLines.push(`      - "${ep}"`));
  }
  const capBlock = Array.isArray(spec.capAdd) ? `\n    cap_add:\n${spec.capAdd.map(c => "      - " + c).join("\n")}` : "";
  const sysctlBlock = Array.isArray(spec.sysctls) ? `\n    sysctls:\n${spec.sysctls.map(s => "      - " + s).join("\n")}` : "";
  const cmdBlock = spec.command ? `\n    command: "${spec.command}"` : "";
  const extraEnv = Array.isArray(spec.env) ? "\n" + spec.env.map(e => "      - " + e).join("\n") : "";
  const vols = (app.volumes || [`/DATA/AppData/${app.id}:/data`]).map(v => `      - ${v}`).join("\n");
  return `name: ${app.id}
services:
  ${app.id}:
image: ${app.image}
container_name: ${app.id}
restart: unless-stopped
security_opt:
  - no-new-privileges:true${cmdBlock}${capBlock}${sysctlBlock}
environment:
  - TZ=UTC
  - PUID=1000
  - PGID=1000${extraEnv}
ports:
${portLines.join("\n")}
volumes:
${vols}`;
}